const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['take'], 'Fun', 'Reply to a sticker to relabel it under your bot\'s name', async ({ sock, from, msg, cfg, args }) => {
  const quoted = msg.message.extendedTextMessage?.contextInfo?.quotedMessage;
  const stickerMsg = quoted?.stickerMessage;
  if (!stickerMsg) return sock.sendMessage(from, { text: 'Reply to a sticker with .take' }, { quoted: msg });
  try {
    const { downloadMediaMessage } = require('@whiskeysockets/baileys');
    const { Image } = require('node-webpmux');
    const buffer = await downloadMediaMessage({ message: { stickerMessage: stickerMsg } }, 'buffer', {});

    const packName = args.join(' ') || cfg.botName;
    const exifAttr = Buffer.from([0x49, 0x49, 0x2A, 0x00, 0x08, 0x00, 0x00, 0x00, 0x01, 0x00, 0x41, 0x57, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x16, 0x00, 0x00, 0x00]);
    const json = { 'sticker-pack-id': 'com.macontech.sticker', 'sticker-pack-name': packName, 'sticker-pack-publisher': cfg.botName, emojis: ['🐺'] };
    const jsonBuffer = Buffer.from(JSON.stringify(json), 'utf-8');
    const exif = Buffer.concat([exifAttr, jsonBuffer]);
    exif.writeUIntLE(jsonBuffer.length, 14, 4);

    const img = new Image();
    await img.load(buffer);
    img.exif = exif;
    await img.save(null);

    await sock.sendMessage(from, { sticker: img.data }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Could not process that sticker.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
